8	function roundCurrency(value) {
9	  if (typeof value !== 'number' || !Number.isFinite(value)) {
10	    throw new TypeError('roundCurrency requires a finite number');
11	  }
12	  return Math.round((value + Number.EPSILON) * 100) / 100;
13	}
14	
15	function money(value) {
16	  return roundCurrency(value).toFixed(2);
17	}
18	
19	module.exports = { roundCurrency, money };
