3	const { billableWeightKg } = require('./weight');
4	const { tierFor, basePriceUsd, shippingUsd } = require('./pricing');
5	const { roundCurrency } = require('./format');
6	
7	// Tax is charged on the parcel subtotal only; shipping is never taxed.
8	const TAX_RATE = 0.07;
