10	// buildInvoice(order) -> {
11	//   id,
12	//   lines: [{ description, quantity, billableKg, tier, amountUsd }],
13	//   shippingZone, shippingUsd,
14	//   subtotalUsd, taxUsd, totalUsd
15	// }
16	//
17	// order = {
18	//   id: string,
19	//   zone: 'domestic' | 'regional' | 'international',
20	//   items: [{ description, quantity?, weightKg, dimensionsCm: { length, width, height } }]
21	// }
22	function buildInvoice(order) {
23	  if (!order || typeof order !== 'object') {
24	    throw new TypeError('buildInvoice requires an order object');
25	  }
26	  if (typeof order.id !== 'string' || order.id === '') {
27	    throw new TypeError('order.id must be a non-empty string');
28	  }
29	  if (!Array.isArray(order.items) || order.items.length === 0) {
30	    throw new TypeError('order.items must be a non-empty array');
31	  }
32	
33	  const lines = [];
34	  let subtotal = 0;
35	  for (const item of order.items) {
36	    const quantity = item.quantity === undefined ? 1 : item.quantity;
37	    if (!Number.isInteger(quantity) || quantity <= 0) {
38	      throw new TypeError('item.quantity must be a positive integer');
39	    }
40	    const kg = billableWeightKg(item.weightKg, item.dimensionsCm);
41	    const amountUsd = roundCurrency(quantity * basePriceUsd(kg));
42	    lines.push({
43	      description: item.description,
44	      quantity,
45	      billableKg: kg,
46	      tier: tierFor(kg),
47	      amountUsd,
48	    });
49	    subtotal += amountUsd;
50	  }
51	
52	  const subtotalUsd = roundCurrency(subtotal);
53	  const shipUsd = shippingUsd(order.zone);
54	  const taxUsd = roundCurrency(TAX_RATE * subtotalUsd);
55	  const totalUsd = roundCurrency(subtotalUsd + shipUsd + taxUsd);
56	
57	  return {
58	    id: order.id,
59	    lines,
60	    shippingZone: order.zone,
61	    shippingUsd: shipUsd,
62	    subtotalUsd,
63	    taxUsd,
64	    totalUsd,
65	  };
66	}
