19	// { code, amountUsd } for the applied discount (see lib/discount.js).
20	//
21	// order = {
22	//   id: string,
23	//   zone: 'domestic' | 'regional' | 'international',
24	//   items: [{ description, quantity?, weightKg, dimensionsCm: { length, width, height } }],
25	//   discountCode?: string
26	// }
27	function buildInvoice(order) {
28	  if (!order || typeof order !== 'object') {
29	    throw new TypeError('buildInvoice requires an order object');
30	  }
31	  if (typeof order.id !== 'string' || order.id === '') {
32	    throw new TypeError('order.id must be a non-empty string');
33	  }
34	  if (!Array.isArray(order.items) || order.items.length === 0) {
35	    throw new TypeError('order.items must be a non-empty array');
36	  }
37	
38	  const lines = [];
39	  let subtotal = 0;
40	  for (const item of order.items) {
41	    const quantity = item.quantity === undefined ? 1 : item.quantity;
42	    if (!Number.isInteger(quantity) || quantity <= 0) {
43	      throw new TypeError('item.quantity must be a positive integer');
44	    }
