48	      description: item.description,
49	      quantity,
50	      billableKg: kg,
51	      tier: tierFor(kg),
52	      amountUsd,
53	    });
54	    subtotal += amountUsd;
55	  }
56	
57	  const subtotalUsd = roundCurrency(subtotal);
58	  let shipUsd = shippingUsd(order.zone);
59	
60	  let discount = null;
61	  let taxUsd;
62	  let totalUsd;
63	
64	  if (order.discountCode !== undefined) {
65	    const result = applyDiscount(order.discountCode, {
66	      subtotalUsd,
67	      shippingUsd: shipUsd,
68	      taxRate: TAX_RATE,
69	    });
