3	const { roundCurrency } = require('./format');
4	
5	// Pricing tiers by billable weight.
6	//
7	// TIER LIMITS ARE INCLUSIVE: a parcel whose billable weight is exactly equal
8	// to a tier's upper limit belongs in that tier. A parcel of exactly 5 kg is a
9	// "small" parcel, and a parcel of exactly 20 kg is a "medium" parcel.
10	//
11	//   small    up to 5 kg inclusive            flat  8.00 USD
12	//   medium   over 5 kg, up to 20 kg incl.    flat 15.00 USD
13	//   large    over 20 kg                      30.00 USD + 1.10 USD per kg over 20
14	const SMALL_MAX_KG = 5;
15	const MEDIUM_MAX_KG = 20;
16	
17	const SMALL_BASE_USD = 8;
18	const MEDIUM_BASE_USD = 15;
19	const LARGE_BASE_USD = 30;
20	const LARGE_PER_KG_USD = 1.1;
21	
22	function tierFor(billableKg) {
23	  if (typeof billableKg !== 'number' || !Number.isFinite(billableKg) || billableKg <= 0) {
24	    throw new TypeError('billableKg must be a positive finite number');
25	  }
26	  if (billableKg <= SMALL_MAX_KG) return 'small';
27	  if (billableKg <= MEDIUM_MAX_KG) return 'medium';
28	  return 'large';
29	}
30	
31	function basePriceUsd(billableKg) {
32	  const tier = tierFor(billableKg);
33	  if (tier === 'small') return SMALL_BASE_USD;
34	  if (tier === 'medium') return MEDIUM_BASE_USD;
35	  return roundCurrency(LARGE_BASE_USD + LARGE_PER_KG_USD * (billableKg - MEDIUM_MAX_KG));
36	}
37	
38	// Flat shipping price per destination zone.
39	const SHIPPING_USD = {
40	  domestic: 4.5,
41	  regional: 9,
42	  international: 22,
43	};
44	
45	function shippingUsd(zone) {
46	  if (!Object.prototype.hasOwnProperty.call(SHIPPING_USD, zone)) {
47	    throw new TypeError('unknown shipping zone: ' + zone);
48	  }
49	  return SHIPPING_USD[zone];
50	}
51	
52	module.exports = { tierFor, basePriceUsd, shippingUsd };
